INSERT INTO public.gym_exercises (id, name, category, secondary_muscles, instructions, image_url, is_default, metric_type)
VALUES
  ('bench_press', 'Barbell Bench Press', 'Hrudník', '{"Triceps","Přední ramena"}', 'Lehněte si na rovnou lavici, lopatky stáhněte k sobě a dolů. Osu spusťte kontrolovaně ke spodní části hrudníku a s výdechem plynule vytlačte nahoru.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0025-EIeI8Vf.gif', TRUE, 'weight_reps'),
  ('dumbbell_bench_press', 'Dumbbell Bench Press', 'Hrudník', '{"Triceps","Přední ramena"}', 'Lehněte si na rovnou lavici. Spouštějte jednoručky kontrolovaně do úrovně hrudníku s roztažením prsních svalů a plynule vytlačte zpět.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0289-SpYC0Kp.gif', TRUE, 'weight_reps'),
  ('incline_barbell_bench', 'Incline Barbell Bench Press', 'Hrudník', '{"Horní hrudník","Přední ramena","Triceps"}', 'Lavici nastavte na úhel 30–45°. Osu spouštějte k horní části hrudníku (klíční kosti) a vytlačujte nahoru bez propínání loktů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0047-3TZduzM.gif', TRUE, 'weight_reps'),
  ('incline_dumbbell_press', 'Incline Dumbbell Press', 'Hrudník', '{"Horní hrudník","Přední ramena","Triceps"}', 'Na lavici se sklonem 30–45° spouštějte jednoručky po stranách hrudníku a vytlačujte je nahoru do jemného dotyku nad horními prsy.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0314-ns0SIbU.gif', TRUE, 'weight_reps'),
  ('decline_barbell_bench', 'Decline Barbell Bench Press', 'Hrudník', '{"Spodní hrudník","Triceps"}', 'V leže hlavou dolů spouštějte činku ke spodní linii prsou. Skvělý cvik na plnost a spodní okraj prsních svalů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0033-GrO65fd.gif', TRUE, 'weight_reps'),
  ('decline_dumbbell_press', 'Decline Dumbbell Press', 'Hrudník', '{"Spodní hrudník","Triceps"}', 'Hlavou dolů kontrolovaně spouštějte jednoručky a silou spodních prsou vytlačujte nahoru.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0301-DwhEmmE.gif', TRUE, 'weight_reps'),
  ('dumbbell_flys', 'Flat Dumbbell Flys', 'Hrudník', '{"Přední ramena"}', 'S mírně pokrčenými lokty spouštějte jednoručky do stran, dokud neucítíte intenzivní protažení prsních svalů, poté stáhněte zpět.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0308-yz9nUhF.gif', TRUE, 'weight_reps'),
  ('incline_dumbbell_flys', 'Incline Dumbbell Flys', 'Hrudník', '{"Horní hrudník","Přední ramena"}', 'Na šikmé lavici rozpažujte paže obloukem do stran a v horní pozici zatněte horní část prsních svalů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0319-ESOd5Pl.gif', TRUE, 'weight_reps'),
  ('decline_dumbbell_flys', 'Decline Dumbbell Flys', 'Hrudník', '{"Spodní hrudník"}', 'Rozpažujte činky na negativně skloněné lavici s důrazem na protažení a zacílení spodních vláken prsního svalu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0305-cwsAI4G.gif', TRUE, 'weight_reps'),
  ('cable_crossover', 'Cable Crossover (High to Low)', 'Hrudník', '{"Vnitřní hrudník","Přední ramena"}', 'Stůjte mírně nakloněni dopředu mezi kladkami. Plynule stahujte madla před tělo a v dolní fázi zkřižte zápěstí pro maximální stisk.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0227-Pr9Rhf4.gif', TRUE, 'weight_reps'),
  ('cable_incline_fly', 'Low Cable Flys (Upper Chest)', 'Hrudník', '{"Horní hrudník","Přední ramena"}', 'Z dolní polohy kladek táhněte madla obloukem zespodu nahoru před hrudník se silným zatnutím klíční části prsních svalů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0179-FVmZVhk.gif', TRUE, 'weight_reps'),
  ('chest_dips', 'Chest Dips', 'Hrudník', '{"Triceps","Přední ramena"}', 'Předkloňte trup dopředu a lokty držte mírně od těla. Klesejte do pravého úhlu v loktech a vytlačte se nahoru.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0251-9WTm7dq.gif', TRUE, 'weight_reps'),
  ('push_ups', 'Push-ups', 'Hrudník', '{"Triceps","Střed těla","Přední ramena"}', 'Dlaně na šířku ramen, tělo jako struna. Klesejte hrudníkem k zemi a silou prsou a paží se vytlačte nahoru.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0662-I4hDWkc.gif', TRUE, 'reps_only'),
  ('diamond_push_ups', 'Diamond Push-ups', 'Hrudník', '{"Triceps","Vnitřní hrudník"}', 'Spojte palce a ukazováčky pod hrudníkem do tvaru diamantu. Výborný cvik na triceps a středovou část prsou.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0302-xXm4nYq.gif', TRUE, 'reps_only'),
  ('pec_deck', 'Pec Deck Machine (Butterfly)', 'Hrudník', '{"Přední ramena"}', 'Pevně opřete záda o lavičku stroje. Plynule svírejte ramena stroje před hrudníkem a na 1 sekundu stlačte prsa k sobě.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0596-v3xmPAR.gif', TRUE, 'weight_reps'),
  ('chest_press_machine', 'Machine Chest Press', 'Hrudník', '{"Triceps","Přední ramena"}', 'Nastavte výšku sedáku tak, aby madla byla v úrovni prsou. Vytlačujte zátěž dopředu s plnou kontrolou.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0576-DOoWcnA.gif', TRUE, 'weight_reps'),
  ('smith_bench_press', 'Smith Machine Bench Press', 'Hrudník', '{"Triceps","Přední ramena"}', 'Vedená dráha činky umožňuje bezpečné zacílení prsních svalů i bez sparingpartnera až do absolutního selhání.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0748-trqKQv2.gif', TRUE, 'weight_reps'),
  ('smith_incline_press', 'Smith Machine Incline Press', 'Hrudník', '{"Horní hrudník","Přední ramena","Triceps"}', 'Nastavte lavičku do multipressu a zaměřte se na horní prsa s perfektní kontrolou tempa.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0757-5v7KYld.gif', TRUE, 'weight_reps'),
  ('deadlift', 'Barbell Conventional Deadlift', 'Záda', '{"Hýždě","Hamstringy","Trapézy","Vzpřimovače páteře"}', 'Osa nad středy chodidel, rovná záda, zpevněný trup. Zvedejte osu plynulým tahem nohou a pánve.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0032-ila4NZS.gif', TRUE, 'weight_reps'),
  ('sumo_deadlift', 'Barbell Sumo Deadlift', 'Záda', '{"Hýždě","Vnitřní stehna","Spodní záda"}', 'Široký postoj, špičky vytočené do stran. Vzpřímený trup zapojuje více nohy a hýždě s menším zatížením beder.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0118-SzX3uzM.gif', TRUE, 'weight_reps'),
  ('pull_ups', 'Pull-ups (Overhand Grip)', 'Záda', '{"Biceps","Zadní ramena","Předloktí"}', 'Široký úchop nadhmatem. Z plného visu táhněte hrudník k hrazdě, lokty stahujte k tělu a lopatky k sobě.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0652-lBDjFxJ.gif', TRUE, 'reps_only'),
  ('chin_ups', 'Chin-ups (Underhand Grip)', 'Záda', '{"Biceps","Široký zádový sval"}', 'Úchop podhmatem na šířku ramen. Masivně zapojuje bicepsy i spodní zádové svaly.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0253-G70mEAJ.gif', TRUE, 'reps_only'),
  ('lat_pulldown', 'Wide-Grip Lat Pulldown', 'Záda', '{"Biceps","Zadní ramena"}', 'Mírný záklon, hrudník vypnutý. Tyč stahujte k horní části hrudníku a v dolní pozici zatněte křídla.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0198-RVwzP10.gif', TRUE, 'weight_reps'),
  ('lat_pulldown_close', 'Cable Straight Arm Pulldown', 'Záda', '{"Biceps","Mezilopatkové svaly"}', 'Úzký neutrální úchop. Adaptér stahujte ke klíčním kostem pro hluboké protažení a šířku zad.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0238-x69MAlq.gif', TRUE, 'weight_reps'),
  ('barbell_rows', 'Barbell Bent-Over Row', 'Záda', '{"Biceps","Trapézy","Zadní ramena"}', 'Předklon 45° s rovnými zády. Přitahujte osu k pupku, lokty veďte těsně podél těla.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0027-eZyBC3j.gif', TRUE, 'weight_reps'),
  ('pendlay_row', 'Pendlay Row', 'Záda', '{"Trapézy","Biceps","Vzpřimovače páteře"}', 'Trup rovnoběžně se zemí. Každé opakování začíná z podlahy výbušným přitažením k hrudníku.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0069-gfk9kD4.gif', TRUE, 'weight_reps'),
  ('dumbbell_row_one_arm', 'Dumbbell One Arm Bent-over Row', 'Záda', '{"Biceps","Zadní ramena"}', 'Jedno koleno a dlaň na lavičce. Přitahujte činku obloukem k boku a stáhněte lopatku.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0292-C0MA9bC.gif', TRUE, 'weight_reps'),
  ('seated_cable_row', 'Seated Cable Row', 'Záda', '{"Biceps","Mezilopatkové svaly","Zadní ramena"}', 'Sedněte si rovně, hrudník dopředu. Táhněte madlo k pasu a silně stiskněte mezilopatkové svaly.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0239-Tq6gbK6.gif', TRUE, 'weight_reps'),
  ('t_bar_row', 'T-Bar Row', 'Záda', '{"Trapézy","Biceps","Střed těla"}', 'Pevný postoj v předklonu. Zvedejte T-osu k hrudníku pro budování maximální tloušťky zad.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0808-4OaumBr.gif', TRUE, 'weight_reps'),
  ('chest_supported_row', 'Chest-Supported Incline Row', 'Záda', '{"Zadní ramena","Biceps","Mezilopatkové svaly"}', 'Lehněte si břichem na šikmou lavici. Eliminujete zatížení spodních zad a čistě izolujete mezilopatkové svaly.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0335-xMjBKwn.gif', TRUE, 'weight_reps'),
  ('straight_arm_pulldown', 'Straight-Arm Cable Pullover', 'Záda', '{"Dlouhá hlava tricepsu","Pilovitý sval"}', 'S lehkým pokrčením v loktech stlačujte tyč obloukem dolů ke stehnům pro izolaci latissimů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0237-DT14T9T.gif', TRUE, 'weight_reps'),
  ('dumbbell_pullover', 'Dumbbell Pullover', 'Záda', '{"Hrudník","Triceps","Pilovitý sval"}', 'Lehněte si horní částí zad napříč přes lavici. Spouštějte činku za hlavu do hlubokého protažení.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0375-9XjtHvS.gif', TRUE, 'weight_reps'),
  ('hyperextension', 'Hyperextension (on Bench)', 'Záda', '{"Hýždě","Hamstringy","Vzpřimovače páteře"}', 'Na šikmé lavici klesejte trupem dolů a plynule se narovnejte do roviny bez nadměrného prohnutí v bedrech.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0488-zkgRrbK.gif', TRUE, 'reps_only'),
  ('good_mornings', 'Barbell Good Mornings', 'Záda', '{"Hamstringy","Hýždě","Vzpřimovače páteře"}', 'Činka na trapézech. S lehkým pokrčením kolen tlačte boky dozadu a předklánějte se v kyčlích.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0044-XlZ4lAC.gif', TRUE, 'weight_reps'),
  ('shrugs_barbell', 'Barbell Shrug', 'Záda', '{"Horní trapézy"}', 'Ve stoji zvedejte ramena přímo vzhůru k uším bez rotace ramen a nahoře zatněte trapézy.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0095-dG7tG5y.gif', TRUE, 'weight_reps'),
  ('shrugs_dumbbell', 'Dumbbell Shrug', 'Záda', '{"Horní trapézy"}', 'Držte jednoručky podél těla a zvedejte ramena nahoru s 1sekundovou výdrží v kontrakci.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0406-NJzBsGJ.gif', TRUE, 'weight_reps'),
  ('military_press', 'Barbell Overhead Press (OHP)', 'Ramena', '{"Přední ramena","Triceps","Střed těla"}', 'Stůjte pevně, zpevněte břicho i hýždě. Vytlačte osu z klíčních kostí přímo nad hlavu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0091-kTbSH9h.gif', TRUE, 'weight_reps'),
  ('shoulder_press_dumbbell', 'Seated Dumbbell Shoulder Press', 'Ramena', '{"Přední ramena","Triceps","Horní hrudník"}', 'Sedněte si s oporou zad. Vytlačujte jednoručky nad hlavu do jemného dotyku nahoře.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0405-znQUdHY.gif', TRUE, 'weight_reps'),
  ('arnold_press', 'Arnold Press', 'Ramena', '{"Přední a střední ramena","Triceps"}', 'Začněte s dlaněmi k obličeji. Během tlaku vzhůru vytáčejte dlaně dopředu a nahoře propněte.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0286-izMnLqz.gif', TRUE, 'weight_reps'),
  ('lateral_raises', 'Dumbbell Lateral Raises', 'Ramena', '{"Trapézy"}', 'Mírný předklon, lokty lehce pokrčené. Zvedejte paže do stran do úrovně ramen, malíčky mírně nahoru.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0334-DsgkuIt.gif', TRUE, 'weight_reps'),
  ('seated_lateral_raises', 'Seated Dumbbell Lateral Raises', 'Ramena', '{"Střední ramena"}', 'Sedněte si na lavičku, eliminujte kmitání nohou a čistě zvedejte činky do stran do roviny ramen.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0403-lyKCLmK.gif', TRUE, 'weight_reps'),
  ('cable_lateral_raise', 'Cable Lateral Raise', 'Ramena', '{"Střední ramena"}', 'Tahem lanka do strany udržujte konstantní tenzi ve svalu po celé dráze pohybu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0190-YTur5nR.gif', TRUE, 'weight_reps'),
  ('incline_lateral_raise', 'Incline Lying Lateral Raise', 'Ramena', '{"Střední ramena"}', 'Lehněte si na bok na šikmou lavici. Extrémní zatížení středního deltového svalu v natažené pozici.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0320-ByX0WxV.gif', TRUE, 'weight_reps'),
  ('front_raises_dumbbell', 'Dumbbell Full Can Lateral Raise', 'Ramena', '{"Přední ramena"}', 'Střídavě zvedejte činky přímo před sebe do výšky očí s mírně pokrčenými lokty.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0311-AQ0mC4Y.gif', TRUE, 'weight_reps'),
  ('front_barbell_raise', 'Barbell Front Raise', 'Ramena', '{"Přední ramena","Horní hrudník"}', 'Uchopte osu nadhmatem a plynule zvedejte před sebe do úrovně ramen.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0041-b2Uoz54.gif', TRUE, 'weight_reps'),
  ('face_pulls', 'Face Pulls (Rope Cable)', 'Ramena', '{"Zadní ramena","Rotátorová manžeta","Trapézy"}', 'Táhněte lano k očím/čelu s roztažením loktů a vnější rotací ramen pro zdravá a kulatá ramena.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0168-hBGWILP.gif', TRUE, 'weight_reps'),
  ('rear_delt_fly_dumbbell', 'Dumbbell Reverse Fly', 'Ramena', '{"Zadní ramena","Mezilopatkové svaly"}', 'V hlubokém předklonu zvedejte činky do stran a soustřeďte se na izolaci zadní hlavy deltů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0383-EAs3xL9.gif', TRUE, 'weight_reps'),
  ('reverse_pec_deck', 'Reverse Pec Deck (Rear Delts)', 'Ramena', '{"Zadní ramena","Trapézy"}', 'Sedněte si čelem k opěrce stroje. Tlačte ramena stroje dozadu s lehkým pokrčením v loktech.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0579-7F1DVzn.gif', TRUE, 'weight_reps'),
  ('cable_rear_delt_fly', 'Cross-Cable Rear Delt Fly', 'Ramena', '{"Zadní ramena","Mezilopatkové svaly"}', 'Uchopte protilehlá lanka bez madel a táhněte paže křížem do stran a dozadu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0225-P5p0j8B.gif', TRUE, 'weight_reps'),
  ('upright_row_barbell', 'Barbell Upright Row V. 2', 'Ramena', '{"Střední ramena","Trapézy"}', 'Osu tahejte podél těla nahoru k hrudníku, lokty vedou pohyb a směřují vzhůru.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0119-83HoW9X.gif', TRUE, 'weight_reps'),
  ('upright_row_cable', 'Cable Wrist Curl', 'Ramena', '{"Střední ramena","Trapézy"}', 'Kladka udržuje plynulý odpor. Táhněte tyč podél trupu k bradě s lokty nahoře.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0247-LrV4s90.gif', TRUE, 'weight_reps'),
  ('landmine_press', 'Landmine Shoulder Press', 'Ramena', '{"Horní hrudník","Triceps","Střed těla"}', 'Jednoručně vytlačujte konec osy nahoru a dopředu. Šetrné k ramenním kloubům.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0573-rUXfn3R.gif', TRUE, 'weight_reps'),
  ('squat', 'Barbell Back Squat', 'Nohy', '{"Hýždě","Hamstringy","Spodní záda"}', 'Osa na trapézech, nohy na šířku ramen. Klesejte boky dolů pod úroveň kolen, váha na celých chodidlech.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0043-qXTaZnJ.gif', TRUE, 'weight_reps'),
  ('front_squat', 'Barbell Front Squat', 'Nohy', '{"Kvadricepsy","Střed těla","Hýždě"}', 'Osa leží na předních ramenech. Trup držte maximálně vzpřímený pro intenzivní zatížení kvadricepsů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0039-IeTIEqg.gif', TRUE, 'weight_reps'),
  ('goblet_squat', 'Goblet Squat (Dumbbell/Kettlebell)', 'Nohy', '{"Kvadricepsy","Hýždě","Břicho"}', 'Činku držte oběma rukama u hrudníku. Dřepujte mezi kolena s rovnými zády a zpevněným břichem.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0312-2NpxjC1.gif', TRUE, 'weight_reps'),
  ('bulgarian_split_squat', 'Bulgarian Split Squats', 'Nohy', '{"Hýždě","Kvadricepsy","Hamstringy"}', 'Jedna noha opřená vzadu o lavičku. Klesejte předním kolenem do pravého úhlu s důrazem na hýždě.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0099-gGNQmVt.gif', TRUE, 'weight_reps'),
  ('leg_press', 'Leg Press 45°', 'Nohy', '{"Kvadricepsy","Hýždě"}', 'Chodidla na šířku ramen na středu desky. Spouštějte závaží do 90° v kolenou a plynule vytlačte přes paty.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0740-tj41Nu6.gif', TRUE, 'weight_reps'),
  ('hack_squat', 'Hack Squat Machine', 'Nohy', '{"Kvadricepsy","Hýždě"}', 'Opřete se zády o opěrku stroje a klesejte do hlubokého dřepu pro maximální napumpování předních stehen.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0739-10Z2DXU.gif', TRUE, 'weight_reps'),
  ('leg_extensions', 'Leg Extensions', 'Nohy', '{"Kvadricepsy"}', 'V sedě zvedejte nohy do úplného propnutí kolen a nahoře na 1 sekundu zatněte kvadricepsy.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0585-my33uHU.gif', TRUE, 'weight_reps'),
  ('lying_leg_curls', 'Lying Leg Curls', 'Nohy', '{"Hamstringy","Lýtka"}', 'Lehněte si na břicho, pánev tlačte do podložky a přitahujte válec k hýždím se zatnutím hamstringů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0599-Zg3XY7P.gif', TRUE, 'weight_reps'),
  ('seated_leg_curls', 'Seated Leg Curls', 'Nohy', '{"Hamstringy"}', 'V sedě stlačujte válec pod kolena se silným zatnutím zadní strany stehen v plném rozsahu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0600-PQ2AtC3.gif', TRUE, 'weight_reps'),
