  ('ex_barbell_decline_wide_grip_press', 'Barbell Decline Wide-grip Press', 'Hrudník', '{"Triceps","Ramena"}', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows out to the sides.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0036-hl8DUh8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_front_raise_and_pullover', 'Barbell Front Raise and Pullover', 'Hrudník', '{"Ramena","Triceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Keep your arms straight and raise the barbell in front of you until it reaches shoulder height. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0040-33AzZeV.gif', TRUE, 'weight_reps'),
  ('ex_barbell_guillotine_bench_press', 'Barbell Guillotine Bench Press', 'Hrudník', '{"Ramena","Triceps"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0045-GXoaSgn.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_decline_bench_press', 'Barbell Reverse Grip Decline Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1256-DotAgEF.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_incline_bench_press', 'Barbell Reverse Grip Incline Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1257-DU7I633.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_bench_press', 'Barbell Wide Bench Press', 'Hrudník', '{"Ramena","Triceps"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0122-JsKq9so.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_reverse_grip_bench_press', 'Barbell Wide Reverse Grip Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1258-945zpRg.gif', TRUE, 'weight_reps'),
  ('ex_cable_bench_press', 'Cable Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the cable machine to chest height and attach the handles. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step forward to create tension in the cables.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0151-7xI5MXA.gif', TRUE, 'weight_reps'),
  ('ex_cable_cross_over_variation', 'Cable Cross-over Variation', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable pulleys to chest height. Stand in the center of the cable machine with one foot in front of the other. Grasp the handles with your palms facing down and your arms extended out to the sides.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0155-0CXGHya.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_fly', 'Cable Decline Fly', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable machine to a decline position. Stand facing away from the machine with your feet shoulder-width apart. Hold the handles with your palms facing forward and your arms extended straight out in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0158-7saC5zz.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_one_arm_press', 'Cable Decline One Arm Press', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the cable machine to a decline position. Stand facing away from the machine and grab the handle with one hand. Position yourself with your back against the decline bench and your arm extended straight in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1260-KHGNa16.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_press', 'Cable Decline Press', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the cable machine to a decline position. Sit on the decline bench facing the cable machine. Grasp the handles with an overhand grip and position them at chest level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1261-2Pya1cP.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_bench_press', 'Cable Incline Bench Press', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the bench to a 45-degree incline. Attach the cable handles to the high pulleys. Sit on the bench facing the cable machine with your feet flat on the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0169-Vh0GsK4.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_fly', 'Cable Incline Fly', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable machine to a low position and attach the handles. Sit on an incline bench with your back against the pad and feet flat on the floor. Grasp the handles with an overhand grip and extend your arms straight out in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0171-tBWXbIT.gif', TRUE, 'weight_reps'),
  ('ex_cable_lying_fly', 'Cable Lying Fly', 'Hrudník', '{"Ramena","Triceps"}', 'Attach the handles to the cables and lie flat on a bench with your feet flat on the ground. Hold the handles with your palms facing each other and your arms extended straight above your chest. Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0185-lJJ7Yq8.gif', TRUE, 'weight_reps'),
  ('ex_cable_middle_fly', 'Cable Middle Fly', 'Hrudník', '{"Ramena","Triceps"}', 'Attach cables to both sides of a cable machine at chest height. Stand in the center of the machine with one foot slightly in front of the other. Grasp the handles with an overhand grip and extend your arms out to the sides.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0188-xLYSdtg.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_decline_chest_fly', 'Cable One Arm Decline Chest Fly', 'Hrudník', '{"Ramena","Triceps"}', 'Attach a D-handle to a low pulley cable machine and set the bench to a decline angle. Lie down on the bench with your head towards the machine and grab the handle with your right hand. Extend your arm straight up above your chest, keeping a slight bend in your elbow.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1262-w4dLzSx.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_fly_on_exercise_ball', 'Cable One Arm Fly on Exercise Ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground. Keep your elbow slightly bent and your palm facing forward.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1263-hHy8tQG.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_incline_fly_on_exercise_ball', 'Cable One Arm Incline Fly on Exercise Ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back against an incline bench. Hold a cable handle in one hand with your arm extended and palm facing inward. Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1264-P14Dz9D.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_incline_press', 'Cable One Arm Incline Press', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable machine to a low pulley position. Sit on an incline bench facing away from the cable machine. Grasp the handle with one hand and bring it up to shoulder height.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1265-GKEH6jj.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_incline_press_on_exercise_ball', 'Cable One Arm Incline Press on Exercise Ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench. Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent. Press the cable handle forward and upward, extending your arm fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1266-6t00BsF.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_lateral_bent_over', 'Cable One Arm Lateral Bent-over', 'Hrudník', '{"Ramena","trapezius"}', 'Stand with your feet shoulder-width apart, facing a cable machine. Grasp the handle with one hand and step back to create tension on the cable. Bend forward at the waist, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0191-dB07vDu.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_press_on_exercise_ball', 'Cable One Arm Press on Exercise Ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and position your arm at chest height, elbow bent. Place your other hand on your hip for stability.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1267-MKIelrR.gif', TRUE, 'weight_reps'),
  ('ex_cable_press_on_exercise_ball', 'Cable Press on Exercise Ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle. Hold the cable handles at chest height with your palms facing down and your elbows bent. Engage your core and press the cable handles forward until your arms are fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1268-vAwm6rK.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_chest_press', 'Cable Seated Chest Press', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the seat height and cable handles to a comfortable position. Sit on the bench with your back straight and feet flat on the floor. Grasp the cable handles with an overhand grip at shoulder height.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2144-nIR4Rwl.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_up_straight_crossovers', 'Cable Standing Up Straight Crossovers', 'Hrudník', '{"Ramena","Triceps"}', 'Stand in the middle of a cable machine with your feet shoulder-width apart. Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides. Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1269-UKWTJWR.gif', TRUE, 'weight_reps'),
  ('ex_alternate_lateral_pulldown', 'Alternate Lateral Pulldown', 'Záda', '{"Biceps","rhomboids"}', 'Sit on the cable machine with your back straight and feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0007-4IKbhHV.gif', TRUE, 'weight_reps'),
  ('ex_archer_pull_up', 'Archer Pull Up', 'Záda', '{"Biceps","Předloktí"}', 'Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3293-72BC5Za.gif', TRUE, 'reps_only'),
  ('ex_assisted_parallel_close_grip_pull_up', 'Assisted Parallel Close Grip Pull-up', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired weight and height. Place your hands on the parallel bars with a close grip, palms facing each other. Hang from the bars with your arms fully extended and your feet off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0015-vrhHa6D.gif', TRUE, 'weight_reps'),
  ('ex_assisted_pull_up', 'Assisted Pull-up', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired weight and height settings. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your feet off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0017-kiJ4Z2K.gif', TRUE, 'weight_reps'),
  ('ex_assisted_standing_chin_up', 'Assisted Standing Chin-up', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired assistance level. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your chest up and shoulders back, engage your core, and slightly bend your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1431-7OeHptV.gif', TRUE, 'weight_reps'),
  ('ex_assisted_standing_pull_up', 'Assisted Standing Pull-up', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired weight and height settings. Stand facing the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1432-f4xtKBj.gif', TRUE, 'weight_reps'),
  ('ex_back_lever', 'Back Lever', 'Záda', '{"Biceps","Předloktí","Střed těla"}', 'Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your knees and tuck them towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3297-GaSzzuh.gif', TRUE, 'reps_only'),
  ('ex_back_pec_stretch', 'Back Pec Stretch', 'Záda', '{"Ramena","Hrudník"}', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out in front of you, parallel to the ground. Cross your arms in front of your body, with your right arm over your left arm.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1405-chfnQnM.gif', TRUE, 'reps_only'),
  ('ex_barbell_bent_arm_pullover', 'Barbell Bent Arm Pullover', 'Záda', '{"Triceps","Hrudník"}', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Lower the barbell behind your head while keeping your arms slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1316-cA9FuWG.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_bent_arm_pullover', 'Barbell Decline Bent Arm Pullover', 'Záda', '{"Triceps","Hrudník"}', 'Lie down on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0034-hMEptv0.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_wide_grip_pullover', 'Barbell Decline Wide-grip Pullover', 'Záda', '{"Triceps","Hrudník"}', 'Lie on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a wide grip and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0037-Hj4FOCd.gif', TRUE, 'weight_reps'),
  ('ex_barbell_incline_row', 'Barbell Incline Row', 'Záda', '{"Biceps","Předloktí"}', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest against the pad and your feet flat on the ground. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0049-dmgMp3n.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_bent_over_row', 'Barbell One Arm Bent Over Row', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip. Bend forward at the hips, keeping your back straight and your head in a neutral position. Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0064-Jsgsc27.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pendlay_row', 'Barbell Pendlay Row', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Bend forward at the hips, keeping your back straight and your chest up. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3017-r0z6xzQ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pullover', 'Barbell Pullover', 'Záda', '{"Hrudník","Triceps"}', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0073-i6LWjok.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pullover_to_press', 'Barbell Pullover to Press', 'Záda', '{"Triceps","Hrudník","Ramena"}', 'Lie flat on a bench with your head at one end and your feet on the ground. Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0022-znLogoF.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_incline_bench_row', 'Barbell Reverse Grip Incline Bench Row', 'Záda', '{"Biceps","Předloktí"}', 'Set up an incline bench at a 45-degree angle. Sit on the bench facing the backrest with your chest against it. Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1317-8d8qJQI.gif', TRUE, 'weight_reps'),
  ('ex_bench_pull_ups', 'Bench Pull-ups', 'Záda', '{"Biceps","Předloktí"}', 'Position yourself under a bar or a sturdy horizontal surface that is at chest height. Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your body straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3019-mExgrF9.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_squatting_row', 'Bodyweight Squatting Row', 'Záda', '{"Biceps","Ramena"}', 'Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended. Lower your body into a squat position, keeping your back straight and your knees behind your toes. From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3168-3xK09Sk.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_close_grip_one_arm_row', 'Bodyweight Standing Close-grip One Arm Row', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip. Bend forward at the hips, keeping your back straight and your core engaged. Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3156-v2DfH14.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_close_grip_row', 'Bodyweight Standing Close-grip Row', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight in front of you, gripping the bar or handles with a close grip.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3158-tig3PXb.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_one_arm_row', 'Bodyweight Standing One Arm Row', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand. Bend forward at the hips, keeping your back straight and your core engaged. Let the dumbbell hang straight down in front of you, with your arm fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3162-xbkPfaw.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_row', 'Bodyweight Standing Row', 'Záda', '{"Biceps","Ramena"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Grasp a bar or handles with an overhand grip, palms facing down. Keep your back straight and core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3166-wd4ds3s.gif', TRUE, 'reps_only'),
  ('ex_cable_bar_lateral_pulldown', 'Cable Bar Lateral Pulldown', 'Záda', '{"Biceps","rhomboids","rear deltoids"}', 'Adjust the cable pulley to a high position and attach a straight bar. Sit facing the cable machine with your feet flat on the ground and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0150-eYnzaCm.gif', TRUE, 'weight_reps'),
  ('ex_cable_cross_over_lateral_pulldown', 'Cable Cross-over Lateral Pulldown', 'Záda', '{"Biceps","rhomboids","rear deltoids"}', 'Attach a cable handle to each side of a cable machine at shoulder height. Stand in the middle of the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step back to create tension in the cables.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0153-OQ1otBN.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_seated_wide_grip_row', 'Cable Decline Seated Wide-grip Row', 'Záda', '{"Biceps","Předloktí"}', 'Sit on the decline bench facing the cable machine with your feet securely placed on the footrests. Grasp the cable attachment with a wide overhand grip, palms facing down. Lean back slightly, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0159-kesXOpB.gif', TRUE, 'weight_reps'),
  ('ex_cable_floor_seated_wide_grip_row', 'Cable Floor Seated Wide-grip Row', 'Záda', '{"Biceps","Předloktí"}', 'Sit on the floor with your legs extended and your back straight. Attach a cable handle to a low pulley and position the cable machine behind you. Grasp the handle with a wide overhand grip, palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0160-veXwo0D.gif', TRUE, 'weight_reps'),
  ('ex_cable_high_row_kneeling', 'Cable High Row (kneeling)', 'Záda', '{"Biceps","Ramena"}', 'Attach a straight bar to a cable machine at chest height. Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart. Sit back on your heels, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0167-ZSJNetl.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_bench_row', 'Cable Incline Bench Row', 'Záda', '{"Biceps","rear deltoids"}', 'Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley. Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent. Grasp the cable handle with an overhand grip and extend your arms fully in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1318-yaMIo4D.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_pushdown', 'Cable Incline Pushdown', 'Záda', '{"Triceps","Ramena"}', 'Attach a straight bar to a high pulley cable machine. Stand facing away from the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0172-1PK5Uo3.gif', TRUE, 'weight_reps'),
  ('ex_cable_lat_pulldown_full_range_of_motion', 'Cable Lat Pulldown Full Range Of Motion', 'Záda', '{"Biceps","rhomboids","rear deltoids"}', 'Sit on the lat pulldown machine with your knees positioned under the pads. Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2330-LEprlgG.gif', TRUE, 'weight_reps'),
  ('ex_cable_lateral_pulldown_with_rope_attachment', 'Cable Lateral Pulldown (with Rope Attachment)', 'Záda', '{"Biceps","Předloktí"}', 'Attach a rope attachment to the cable machine at a high position. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing each other.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0177-CuaWCmC.gif', TRUE, 'weight_reps'),
  ('ex_cable_lateral_pulldown_with_v_bar', 'Cable Lateral Pulldown with V-Bar', 'Záda', '{"Biceps","Předloktí"}', 'Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip. Adjust the knee pad so that your thighs are secured under it. Keep your back straight and lean back slightly.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2616-4c9BhzB.gif', TRUE, 'weight_reps'),
  ('ex_cable_lying_extension_pullover_with_rope_attachment', 'Cable Lying Extension Pullover (with Rope Attachment)', 'Záda', '{"Triceps","Ramena"}', 'Attach a rope to a cable machine and set the pulley at the highest position. Lie down on a bench with your head towards the cable machine. Hold the rope with both hands and extend your arms straight up above your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0184-Q2Eu1Ax.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_bent_over_row', 'Cable One Arm Bent Over Row', 'Záda', '{"Biceps","Předloktí"}', 'Stand facing a cable machine with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0189-EIsE3u8.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_pulldown', 'Cable One Arm Pulldown', 'Záda', '{"Biceps","Předloktí"}', 'Attach a single handle to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip and extend your arm fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3563-U5INZY6.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_straight_back_high_row_kneeling', 'Cable One Arm Straight Back High Row (kneeling)', 'Záda', '{"Biceps","Ramena"}', 'Attach a handle to a cable machine at waist height. Kneel down facing the cable machine and grab the handle with one hand. Keep your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0193-WrYPP2g.gif', TRUE, 'weight_reps'),
  ('ex_cable_palm_rotational_row', 'Cable Palm Rotational Row', 'Záda', '{"Biceps","Předloktí"}', 'Attach a handle to a cable machine at waist height. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip, palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1319-OmQ8w0p.gif', TRUE, 'weight_reps'),
  ('ex_cable_pulldown_pro_lat_bar', 'Cable Pulldown (pro Lat Bar)', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor. Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart. Sit down and lean back slightly, keeping your chest up and your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0197-qdRxqCj.gif', TRUE, 'weight_reps'),
  ('ex_cable_pushdown_straight_arm_v_2', 'Cable Pushdown (straight Arm) V. 2', 'Záda', '{"Triceps","Ramena"}', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0199-PskORrA.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_snatch', 'Barbell One Arm Snatch', 'Ramena', '{"Trapézy","Předloktí","Střed těla"}', 'Stand with your feet shoulder-width apart, toes pointing slightly outwards. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0067-xHKN2s8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rear_delt_raise', 'Barbell Rear Delt Raise', 'Ramena', '{"Trapézy","rhomboids"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0075-Ln9iTbU.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rear_delt_row', 'Barbell Rear Delt Row', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0076-S9zHIvU.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_behind_head_military_press', 'Barbell Seated Behind Head Military Press', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it down to shoulder level, behind your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0086-ngPpyRS.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_bradford_rocky_press', 'Barbell Seated Bradford Rocky Press', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0087-0dCyly0.gif', TRUE, 'weight_reps'),
  ('ex_barbell_skier', 'Barbell Skier', 'Ramena', '{"Triceps","Střed těla"}', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0100-4Leypho.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_bradford_press', 'Barbell Standing Bradford Press', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip. Press the barbell overhead, fully extending your arms. Lower the barbell back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0105-dCPESfR.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_close_grip_military_press', 'Barbell Standing Close Grip Military Press', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows close to your body. Press the barbell overhead, extending your arms fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1456-wdRZISl.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_front_raise_over_head', 'Barbell Standing Front Raise Over Head', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip. Keep your back straight and engage your core. Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0107-S8mo30S.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_wide_military_press', 'Barbell Standing Wide Military Press', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width. Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar. Press the barbell overhead, extending your arms fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1457-Kyd9Rz5.gif', TRUE, 'weight_reps'),
  ('ex_barbell_thruster', 'Barbell Thruster', 'Ramena', '{"Kvadricepsy","Hýždě","Hamstringy"}', 'Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip. Lower into a squat position by bending your knees and pushing your hips back. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3305-f7Y9eDZ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_upright_row', 'Barbell Upright Row', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0120-UDlhcO8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_upright_row_v_3', 'Barbell Upright Row V. 3', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0121-fI18Rbc.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_grip_upright_row', 'Barbell Wide-grip Upright Row', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0123-RgJDRR1.gif', TRUE, 'weight_reps'),
  ('ex_cable_alternate_shoulder_press', 'Cable Alternate Shoulder Press', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip. Position your hands at shoulder height, with your palms facing forward. Keep your core engaged and your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0148-KHPZL0b.gif', TRUE, 'weight_reps'),
  ('ex_cable_cross_over_revers_fly', 'Cable Cross-over Revers Fly', 'Ramena', '{"rhomboids","trapezius"}', 'Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine. Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart. Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0154-aqvSOQE.gif', TRUE, 'weight_reps'),
  ('ex_cable_forward_raise', 'Cable Forward Raise', 'Ramena', '{"Triceps","Předloktí"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you. Keeping your arms straight, raise the cable handle up to shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0161-hvHhCv8.gif', TRUE, 'weight_reps'),
  ('ex_cable_front_raise', 'Cable Front Raise', 'Ramena', '{"Triceps","Předloktí"}', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip. Keep your back straight and your core engaged. Raise the cable handle in front of you, keeping your arms straight and your palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0162-u2X71Np.gif', TRUE, 'weight_reps'),
  ('ex_cable_kneeling_rear_delt_row_with_rope_male', 'Cable Kneeling Rear Delt Row (with Rope) (male)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Attach a rope handle to a low cable pulley and kneel down facing the machine. Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you. Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3697-G61cXLk.gif', TRUE, 'weight_reps'),
  ('ex_cable_lateral_raise', 'Cable Lateral Raise', 'Ramena', '{"Trapézy","Triceps"}', 'Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip. Keep your arms straight and your core engaged. Raise your arms out to the sides until they are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0178-goJ6ezq.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_lateral_raise', 'Cable One Arm Lateral Raise', 'Ramena', '{"Trapézy","Triceps"}', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable. Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0192-wEulIzp.gif', TRUE, 'weight_reps'),
  ('ex_cable_rear_delt_row_stirrups', 'Cable Rear Delt Row (stirrups)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Attach a stirrup handle to a low cable pulley and stand facing the machine. Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0202-yUdIGNs.gif', TRUE, 'weight_reps'),
  ('ex_cable_rear_delt_row_with_rope', 'Cable Rear Delt Row (with Rope)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Attach a rope handle to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope handle with an overhand grip, palms facing each other.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0203-wqNPGCg.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_rear_lateral_raise', 'Cable Seated Rear Lateral Raise', 'Ramena', '{"Trapézy","rhomboids"}', 'Sit on a bench facing the cable machine with your feet flat on the ground. Grasp the cable handles with an overhand grip and extend your arms straight in front of you. Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0215-x825CZm.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_shoulder_internal_rotation', 'Cable Seated Shoulder Internal Rotation', 'Ramena', '{"rotator cuff","Triceps"}', 'Sit on a bench or chair facing the cable machine with your feet flat on the ground. Hold the cable handle with your arm extended straight out in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back and down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0216-YPoVrBi.gif', TRUE, 'weight_reps'),
  ('ex_cable_shoulder_press', 'Cable Shoulder Press', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Adjust the cable machine so that the handles are at shoulder height. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0219-PzQanLE.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_rear_delt_row_with_rope', 'Cable Standing Rear Delt Row (with Rope)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable. Keep your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0233-ZfyAGhK.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_shoulder_external_rotation', 'Cable Standing Shoulder External Rotation', 'Ramena', '{"rotator cuff","trapezius"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with your arm extended in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0235-FWdVhcW.gif', TRUE, 'weight_reps'),
  ('ex_cable_supine_reverse_fly', 'Cable Supine Reverse Fly', 'Ramena', '{"trapezius","rhomboids"}', 'Attach a D-handle to a low pulley cable machine and lie face down on a flat bench. Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you. Keeping your arms straight, raise them out to the sides until they are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0240-PQcUlDi.gif', TRUE, 'weight_reps'),
  ('ex_cable_upright_row', 'Cable Upright Row', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip. Keep your back straight and your core engaged throughout the exercise. Pull the cable attachment straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0246-cALKspW.gif', TRUE, 'weight_reps'),
  ('ex_dumbbell_arnold_press', 'Dumbbell Arnold Press', 'Ramena', '{"Triceps","upper chest"}', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2137-Xy4jlWA.gif', TRUE, 'weight_reps'),
  ('ex_dumbbell_arnold_press_v_2', 'Dumbbell Arnold Press V. 2', 'Ramena', '{"Triceps","upper chest"}', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0287-eOrFCnx.gif', TRUE, 'weight_reps'),
  ('ex_all_fours_squad_stretch', 'All Fours Squad Stretch', 'Nohy', '{"Hamstringy","Hýždě"}', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Extend one leg straight back, keeping your knee bent and your foot flexed. Slowly lower your hips towards the ground, feeling a stretch in your quads.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1512-qBcKorM.gif', TRUE, 'reps_only'),
  ('ex_ankle_circles', 'Ankle Circles', 'Nohy', '{"ankle stabilizers"}', 'Sit on the ground with your legs extended in front of you. Lift one leg off the ground and rotate your ankle in a circular motion. Perform the desired number of circles in one direction, then switch to the other direction.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1368-uL9CsKm.gif', TRUE, 'reps_only'),
  ('ex_arms_apart_circular_toe_touch_male', 'Arms Apart Circular Toe Touch (male)', 'Nohy', '{"Hamstringy","Kvadricepsy","Lýtka"}', 'Stand with your feet shoulder-width apart and arms extended to the sides. Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand. As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3214-RtyAsy1.gif', TRUE, 'reps_only'),
  ('ex_backward_jump', 'Backward Jump', 'Nohy', '{"Hamstringy","Hýždě","Lýtka"}', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump backwards, pushing off with both feet. Land softly on the balls of your feet, bending your knees to absorb the impact.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1473-SaDOwk7.gif', TRUE, 'reps_only'),
  ('ex_balance_board', 'Balance Board', 'Nohy', '{"Lýtka","Hamstringy","Hýždě"}', 'Place the balance board on a flat surface. Step onto the balance board with one foot, ensuring it is centered. Slowly shift your weight onto the foot on the balance board, keeping your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0020-xAySMB0.gif', TRUE, 'reps_only'),
  ('ex_barbell_bench_front_squat', 'Barbell Bench Front Squat', 'Nohy', '{"Hamstringy","Hýždě","Lýtka"}', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone. Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground. Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0024-Y7YcmIJ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_bench_squat', 'Barbell Bench Squat', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Set up a barbell on a squat rack at chest height. Stand facing away from the rack, with your feet shoulder-width apart. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0026-W9pFVv1.gif', TRUE, 'weight_reps'),
  ('ex_barbell_clean_and_press', 'Barbell Clean and Press', 'Nohy', '{"Hamstringy","Hýždě","Ramena"}', 'Stand with your feet shoulder-width apart and the barbell on the floor in front of you. Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0028-SGY8Zui.gif', TRUE, 'weight_reps'),
  ('ex_barbell_clean_grip_front_squat', 'Barbell Clean-grip Front Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward. Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair. Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0029-qi996YS.gif', TRUE, 'weight_reps'),
  ('ex_barbell_floor_calf_raise', 'Barbell Floor Calf Raise', 'Nohy', '{"Hamstringy"}', 'Place a barbell on the floor in front of you. Stand with the balls of your feet on the edge of the barbell, with your heels hanging off. Hold onto a stable object for balance if needed.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1370-2IHEa2T.gif', TRUE, 'weight_reps'),
  ('ex_barbell_front_squat', 'Barbell Front Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, toes slightly turned out. Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0042-zG0zs85.gif', TRUE, 'weight_reps'),
  ('ex_barbell_full_squat_back_pov', 'Barbell Full Squat (back Pov)', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1461-DhMl549.gif', TRUE, 'weight_reps'),
  ('ex_barbell_full_squat_side_pov', 'Barbell Full Squat (side Pov)', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1462-iYzB0Cz.gif', TRUE, 'weight_reps'),
  ('ex_barbell_full_zercher_squat', 'Barbell Full Zercher Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1545-vR1vold.gif', TRUE, 'weight_reps'),
  ('ex_barbell_glute_bridge', 'Barbell Glute Bridge', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Start by lying flat on your back on the ground with your knees bent and feet flat on the floor. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1409-qKBpF7I.gif', TRUE, 'weight_reps'),
  ('ex_barbell_glute_bridge_two_legs_on_bench_male', 'Barbell Glute Bridge Two Legs on Bench (male)', 'Nohy', '{"Hamstringy","Střed těla"}', 'Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3562-qg2PGl6.gif', TRUE, 'weight_reps'),
  ('ex_barbell_hack_squat', 'Barbell Hack Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart and your toes slightly turned out. Hold the barbell behind your legs, resting it on your upper thighs. Lower your body by bending at the knees and hips, keeping your back straight and your chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0046-5VCj6iH.gif', TRUE, 'weight_reps'),
  ('ex_barbell_high_bar_squat', 'Barbell High Bar Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Place the barbell on your upper back, resting it on your traps. Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1436-Gnfo4FM.gif', TRUE, 'weight_reps'),
  ('ex_barbell_jefferson_squat', 'Barbell Jefferson Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist. Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0051-pkSoCW9.gif', TRUE, 'weight_reps'),
  ('ex_barbell_jump_squat', 'Barbell Jump Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Once you reach the bottom of the squat, explode upwards by jumping off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0053-1gFNTZV.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lateral_lunge', 'Barbell Lateral Lunge', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back. Take a big step to the side with your right foot, keeping your left foot planted. Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1410-py1HSzx.gif', TRUE, 'weight_reps'),
  ('ex_barbell_low_bar_squat', 'Barbell Low Bar Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and the barbell resting on your upper back. Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground or slightly below.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1435-bTpEUcm.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lunge', 'Barbell Lunge', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back. Take a step forward with your right foot, keeping your torso upright. Lower your body by bending your right knee until your thigh is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0054-t8iSghb.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_lifting_on_hip', 'Barbell Lying Lifting (on Hip)', 'Nohy', '{"Hamstringy","Kvadricepsy"}', 'Lie flat on your back on a bench with your feet flat on the ground and your knees bent. Hold the barbell with an overhand grip and position it on your hips. Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0058-SNFfUff.gif', TRUE, 'weight_reps'),
  ('ex_barbell_narrow_stance_squat', 'Barbell Narrow Stance Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0063-elhhVgj.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_side_deadlift', 'Barbell One Arm Side Deadlift', 'Nohy', '{"Hamstringy","Kvadricepsy","Spodní záda"}', 'Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip. Keep your back straight and your core engaged. Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0066-2DxtqHL.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_leg_squat', 'Barbell One Leg Squat', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Lift one foot off the ground and extend it forward, keeping it parallel to the ground. Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0068-uKyN64F.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rack_pull', 'Barbell Rack Pull', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Set up a barbell on a rack at knee height. Stand with your feet shoulder-width apart, toes pointing slightly outwards. Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0074-za9Ni4z.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rear_lunge_v_2', 'Barbell Rear Lunge V. 2', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Take a step backward with your right foot, landing on the ball of your foot. Bend both knees to lower your body until your left thigh is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0077-62Nw60O.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_calf_raise', 'Barbell Seated Calf Raise', 'Nohy', '{"Hamstringy"}', 'Sit on a bench with your feet flat on the floor and a barbell resting on your thighs. Place the balls of your feet on a raised platform, such as a block or step. Lower your heels as far as possible, feeling a stretch in your calves.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1371-ipvgBnC.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_good_morning', 'Barbell Seated Good Morning', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Sit on a bench with your feet flat on the ground and a barbell resting on your upper back. Keep your back straight and your chest up. Slowly hinge forward at the hips, lowering your torso towards the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0090-d960PgE.gif', TRUE, 'weight_reps'),
  ('ex_barbell_side_split_squat', 'Barbell Side Split Squat', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a barbell across your upper back, resting it on your traps. Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0098-W31mMjd.gif', TRUE, 'weight_reps'),
  ('ex_barbell_side_split_squat_v_2', 'Barbell Side Split Squat V. 2', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards. Hold a barbell across your upper back, resting it on your shoulders. Take a big step to the side with your right foot, keeping your left foot planted.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0097-HUEqZ1y.gif', TRUE, 'weight_reps'),
  ('ex_barbell_single_leg_deadlift', 'Barbell Single Leg Deadlift', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip. Shift your weight onto your left foot and lift your right foot slightly off the ground. Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1756-gEyURal.gif', TRUE, 'weight_reps'),
  ('ex_barbell_speed_squat', 'Barbell Speed Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0101-euI1BwR.gif', TRUE, 'weight_reps'),
  ('ex_barbell_split_squat_v_2', 'Barbell Split Squat V. 2', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Take a large step forward with your right foot, keeping your torso upright. Lower your body by bending your knees and hips until your right thigh is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2810-HBYyX94.gif', TRUE, 'weight_reps'),
  ('ex_barbell_squat_on_knees', 'Barbell Squat (on Knees)', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward. Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart. Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0102-oR7O9LW.gif', TRUE, 'weight_reps'),
  ('ex_barbell_squat_jump_step_rear_lunge', 'Barbell Squat Jump Step Rear Lunge', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Explode upwards, jumping off the ground as high as you can.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2798-RYcV1kH.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_leg_calf_raise', 'Barbell Standing Leg Calf Raise', 'Nohy', '{"Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart and place a barbell across your upper back. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0108-rGwhJ5o.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_rocking_leg_calf_raise', 'Barbell Standing Rocking Leg Calf Raise', 'Nohy', '{"Hamstringy","Kvadricepsy"}', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Raise your heels off the ground as high as possible, balancing on the balls of your feet. Slowly lower your heels back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0111-6HiHHe0.gif', TRUE, 'weight_reps'),
  ('ex_barbell_step_up', 'Barbell Step-up', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand in front of a bench or step with a barbell resting on your upper back. Place one foot on the bench or step, ensuring your entire foot is in contact with the surface. Push through your heel and step up onto the bench or step, fully extending your hip and knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0114-Kxquu2E.gif', TRUE, 'weight_reps'),
  ('ex_barbell_stiff_leg_good_morning', 'Barbell Stiff Leg Good Morning', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the barbell across your upper back, resting it on your traps. Keeping your back straight, hinge forward at the hips, pushing your glutes back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0115-JrOHAZc.gif', TRUE, 'weight_reps'),
  ('ex_barbell_straight_leg_deadlift', 'Barbell Straight Leg Deadlift', 'Nohy', '{"Hýždě","Spodní záda"}', 'Stand with your feet shoulder-width apart and your toes pointing forward. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0116-hrVQWvE.gif', TRUE, 'weight_reps'),
  ('ex_barbell_sumo_deadlift', 'Barbell Sumo Deadlift', 'Nohy', '{"Hamstringy","Kvadricepsy","Spodní záda"}', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards. Place a barbell on the ground in front of you, centered between your feet. Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0117-KgI0tqW.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_squat', 'Barbell Wide Squat', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0124-s7HX1BY.gif', TRUE, 'weight_reps'),
  ('ex_barbell_zercher_squat', 'Barbell Zercher Squat', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0127-LSTChY9.gif', TRUE, 'weight_reps'),
  ('ex_basic_toe_touch_male', 'Basic Toe Touch (male)', 'Nohy', '{"Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down towards your toes with your hands, keeping your legs as straight as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3212-BbfB8Gb.gif', TRUE, 'reps_only'),
  ('ex_bench_hip_extension', 'Bench Hip Extension', 'Nohy', '{"Hamstringy"}', 'Sit on a bench with your back against the bench and your feet flat on the ground. Place your hands on the bench for support. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0130-u27Kcdz.gif', TRUE, 'reps_only'),
  ('ex_assisted_triceps_dip_kneeling', 'Assisted Triceps Dip (kneeling)', 'Ruce', '{"Hrudník","Ramena"}', 'Adjust the machine to your desired weight and height. Kneel down on the pad facing the machine, with your hands gripping the handles. Lower your body by bending your elbows, keeping your back straight and close to the machine.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0019-J60bN17.gif', TRUE, 'weight_reps'),
  ('ex_barbell_alternate_biceps_curl', 'Barbell Alternate Biceps Curl', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward. Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps. Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0023-Yza7XrQ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_biceps_curl_with_arm_blaster', 'Barbell Biceps Curl (with Arm Blaster)', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Place your upper arms against the arm blaster, keeping your elbows close to your torso. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2407-aee2Fcj.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_close_grip_to_skull_press', 'Barbell Decline Close Grip to Skull Press', 'Ruce', '{"Hrudník","Ramena"}', 'Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip. Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary. Pause for a moment, then extend your arms to press the barbell back up to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0035-LMGXZn8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_drag_curl', 'Barbell Drag Curl', 'Ruce', '{"Předloktí"}', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Let the barbell hang at arm''s length in front of your thighs. Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0038-IENzBdA.gif', TRUE, 'weight_reps'),
  ('ex_barbell_incline_close_grip_bench_press', 'Barbell Incline Close Grip Bench Press', 'Ruce', '{"Hrudník","Ramena"}', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1719-gx7s7uF.gif', TRUE, 'weight_reps'),
  ('ex_barbell_incline_reverse_grip_press', 'Barbell Incline Reverse-grip Press', 'Ruce', '{"Hrudník","Ramena"}', 'Set up an incline bench at a 45-degree angle. Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0048-641mIfk.gif', TRUE, 'weight_reps'),
  ('ex_barbell_jm_bench_press', 'Barbell Jm Bench Press', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows tucked in close to your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0052-ZsiqXYa.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_back_of_the_head_tricep_extension', 'Barbell Lying Back Of The Head Tricep Extension', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1720-yg8Totb.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_close_grip_press', 'Barbell Lying Close-grip Press', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0055-EcaV7aL.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_close_grip_triceps_extension', 'Barbell Lying Close-grip Triceps Extension', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up. Extend your arms fully, lifting the barbell above your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0056-HJ63mSO.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_extension', 'Barbell Lying Extension', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0057-EMpUwRI.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_preacher_curl', 'Barbell Lying Preacher Curl', 'Ruce', '{"Předloktí"}', 'Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0059-SYJ4Bkt.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_triceps_extension', 'Barbell Lying Triceps Extension', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0061-iZop9xO.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_floor_press', 'Barbell One Arm Floor Press', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest. Slowly lower the barbell towards your chest, keeping your elbow close to your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0065-vtusOWT.gif', TRUE, 'weight_reps'),
  ('ex_barbell_palms_down_wrist_curl_over_a_bench', 'Barbell Palms Down Wrist Curl Over a Bench', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down. Hold a barbell with an overhand grip, hands shoulder-width apart. Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1411-yzYH9pI.gif', TRUE, 'weight_reps'),
  ('ex_barbell_palms_up_wrist_curl_over_a_bench', 'Barbell Palms Up Wrist Curl Over a Bench', 'Ruce', '{"Biceps","Ramena"}', 'Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up. Rest your forearms on the bench, allowing your wrists to hang off the edge. Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1412-SJAA2IQ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pin_presses', 'Barbell Pin Presses', 'Ruce', '{"Ramena"}', 'Set up a barbell on a power rack at chest height. Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart. Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1751-bndCa3Q.gif', TRUE, 'weight_reps'),
  ('ex_barbell_preacher_curl', 'Barbell Preacher Curl', 'Ruce', '{"Předloktí"}', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support. Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0070-qOgPVf6.gif', TRUE, 'weight_reps'),
  ('ex_barbell_prone_incline_curl', 'Barbell Prone Incline Curl', 'Ruce', '{"Předloktí"}', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting against it. Hold a barbell with an underhand grip, shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0072-WLvTAv5.gif', TRUE, 'weight_reps'),
  ('ex_barbell_revers_wrist_curl_v_2', 'Barbell Revers Wrist Curl V. 2', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and your knees bent. Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off the edge.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0079-qDnGfDb.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_close_grip_bench_press', 'Barbell Reverse Close-grip Bench Press', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a reverse grip, hands shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2187-YqJw82s.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_skullcrusher', 'Barbell Reverse Grip Skullcrusher', 'Ruce', '{"Předloktí"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart. Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1721-yRLPCLu.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_preacher_curl', 'Barbell Reverse Preacher Curl', 'Ruce', '{"Předloktí"}', 'Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip. Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0081-4LIG9xr.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_wrist_curl', 'Barbell Reverse Wrist Curl', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the barbell towards your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0082-LsZkfU6.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_close_grip_behind_neck_triceps_extension', 'Barbell Seated Close Grip Behind Neck Triceps Extension', 'Ruce', '{"Ramena"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with a close grip behind your neck, palms facing forward. Keep your elbows close to your head and slowly lower the barbell towards the back of your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1718-4CBIBOM.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_close_grip_concentration_curl', 'Barbell Seated Close-grip Concentration Curl', 'Ruce', '{"Předloktí"}', 'Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart. Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0089-1V1gj1u.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_overhead_triceps_extension', 'Barbell Seated Overhead Triceps Extension', 'Ruce', '{"Ramena"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead. Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0092-5uFK1xr.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_back_wrist_curl', 'Barbell Standing Back Wrist Curl', 'Ruce', '{"Biceps","Ramena"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip. Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body. Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0104-2qTvJAZ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_close_grip_curl', 'Barbell Standing Close Grip Curl', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0106-4dUn2iv.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_concentration_curl', 'Barbell Standing Concentration Curl', 'Ruce', '{"Předloktí"}', 'Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up. Rest your opposite hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2414-vsMcDi9.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_overhead_triceps_extension', 'Barbell Standing Overhead Triceps Extension', 'Ruce', '{"Ramena"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip. Raise the barbell overhead, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0109-dZl9Q27.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_reverse_grip_curl', 'Barbell Standing Reverse Grip Curl', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0110-LWuA3aZ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_wide_grip_biceps_curl', 'Barbell Standing Wide Grip Biceps Curl', 'Ruce', '{"Předloktí"}', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart. Keep your back straight and your elbows close to your torso. Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1629-faHKVkK.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_wide_grip_curl', 'Barbell Standing Wide-grip Curl', 'Ruce', '{"Předloktí","Ramena"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body. Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0113-NdIb5Z1.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wrist_curl', 'Barbell Wrist Curl', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip. Allow the barbell to roll down to your fingertips, keeping your wrists straight. Slowly curl the barbell up towards your forearms by flexing your wrists.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0126-82LxxkW.gif', TRUE, 'weight_reps'),
  ('ex_bench_dip_knees_bent', 'Bench Dip (knees Bent)', 'Ruce', '{"Hrudník","Ramena"}', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0129-RrLske5.gif', TRUE, 'reps_only'),
  ('ex_bench_dip_on_floor', 'Bench Dip on Floor', 'Ruce', '{"Hrudník","Ramena"}', 'Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1399-9RT8oQW.gif', TRUE, 'reps_only'),
  ('ex_biceps_leg_concentration_curl', 'Biceps Leg Concentration Curl', 'Ruce', '{"Předloktí"}', 'Sit on a bench with your legs spread apart and your feet flat on the ground. Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee. With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1770-sJFIDIp.gif', TRUE, 'reps_only'),
  ('ex_biceps_pull_up', 'Biceps Pull-up', 'Ruce', '{"Předloktí","Ramena"}', 'Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart. Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar. Pause at the top of the movement, then slowly lower yourself back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0140-guT8YnS.gif', TRUE, 'reps_only'),
  ('ex_body_up', 'Body-up', 'Ruce', '{"Hrudník","Ramena"}', 'Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward. Extend your legs out in front of you, keeping your heels on the ground and your body straight. Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0137-U6G2gk9.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_kneeling_triceps_extension', 'Bodyweight Kneeling Triceps Extension', 'Ruce', '{"Ramena","Hrudník"}', 'Kneel down on the ground with your knees hip-width apart. Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward. Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1771-s0HKO2I.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_side_lying_biceps_curl', 'Bodyweight Side Lying Biceps Curl', 'Ruce', '{"Předloktí"}', 'Lie on your side with your legs extended and your head supported by your arm. Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1769-gscGLOU.gif', TRUE, 'reps_only'),
  ('ex_cable_alternate_triceps_extension', 'Cable Alternate Triceps Extension', 'Ruce', '{"Ramena"}', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle. Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0149-Gchi5Tr.gif', TRUE, 'weight_reps'),
  ('ex_cable_close_grip_curl', 'Cable Close Grip Curl', 'Ruce', '{"Předloktí"}', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an underhand grip, hands shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1630-BCGQ6J5.gif', TRUE, 'weight_reps'),
  ('ex_cable_concentration_curl', 'Cable Concentration Curl', 'Ruce', '{"Předloktí"}', 'Sit on a bench or chair with your feet flat on the floor and your knees slightly bent. Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh. Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1631-NvfE43H.gif', TRUE, 'weight_reps'),
  ('ex_cable_concentration_extension_on_knee', 'Cable Concentration Extension (on Knee)', 'Ruce', '{"Předloktí"}', 'Sit on a bench or chair with your knees bent and feet flat on the ground. Hold the cable handle with your right hand and place your elbow on the inside of your right knee. Extend your arm fully, keeping your elbow stationary and close to your knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0152-Db7eEgw.gif', TRUE, 'weight_reps'),
  ('ex_cable_curl', 'Cable Curl', 'Ruce', '{"Předloktí"}', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable attachment with an underhand grip, palms facing up. Keep your elbows close to your sides and your upper arms stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0868-G08RZcQ.gif', TRUE, 'weight_reps'),
  ('ex_3_4_sit_up', 'Three-quarter Sit-up', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0001-2gPfomN.gif', TRUE, 'reps_only'),
  ('ex_45_side_bend', '45° Side Bend', 'Břicho', '{"obliques"}', 'Stand with your feet shoulder-width apart and your arms extended straight down by your sides. Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee. Pause for a moment at the bottom, then slowly return to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0002-Hy9D21L.gif', TRUE, 'reps_only'),
  ('ex_alternate_heel_touchers', 'Alternate Heel Touchers', 'Břicho', '{"obliques"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight out to the sides, parallel to the ground. Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0006-qaZVsGk.gif', TRUE, 'reps_only'),
  ('ex_arm_slingers_hanging_bent_knee_legs', 'Arm Slingers Hanging Bent Knee Legs', 'Břicho', '{"Ramena","back"}', 'Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle. Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible. Slowly lower your legs back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2355-uWpxD4v.gif', TRUE, 'reps_only'),
  ('ex_arm_slingers_hanging_straight_legs', 'Arm Slingers Hanging Straight Legs', 'Břicho', '{"Ramena","back"}', 'Hang from a pull-up bar with your arms fully extended and your legs straight down. Engage your core and lift your legs up in front of you until they are parallel to the ground. Hold for a moment at the top, then slowly lower your legs back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2333-PXTIwgu.gif', TRUE, 'reps_only'),
  ('ex_arms_overhead_full_sit_up_male', 'Arms Overhead Full Sit-up (male)', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms overhead, keeping them straight. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3204-NAkmgdx.gif', TRUE, 'reps_only'),
  ('ex_barbell_press_sit_up', 'Barbell Press Sit-up', 'Břicho', '{"Ramena","Hrudník"}', 'Lie flat on your back on a mat with your knees bent and feet flat on the ground. Hold the barbell with an overhand grip, resting it on your chest. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0071-wnEscH8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_twist', 'Barbell Seated Twist', 'Břicho', '{"obliques","Spodní záda"}', 'Sit on a flat bench with your feet flat on the ground and your knees bent. Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent. Engage your core and slowly twist your torso to one side, keeping your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0094-dFSNDOA.gif', TRUE, 'weight_reps'),
  ('ex_barbell_side_bent_v_2', 'Barbell Side Bent V. 2', 'Břicho', '{"obliques","Spodní záda"}', 'Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down. Keep your back straight and core engaged throughout the exercise. Slowly bend your torso to the right side, lowering the barbell towards your right knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0096-i4JkUaL.gif', TRUE, 'weight_reps'),
  ('ex_barbell_sitted_alternate_leg_raise', 'Barbell Sitted Alternate Leg Raise', 'Břicho', '{"Ohybače kyčlí"}', 'Sit on a bench with your back straight and hold a barbell across your thighs. Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground. Lower the raised leg back down and repeat with the other leg.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2799-G7xoEzr.gif', TRUE, 'weight_reps'),
  ('ex_barbell_sitted_alternate_leg_raise_female', 'Barbell Sitted Alternate Leg Raise (female)', 'Břicho', '{"Ohybače kyčlí","Kvadricepsy"}', 'Sit on a bench with your back straight and hold a barbell across your thighs. Place your hands on the sides of the bench for support. Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2800-BCs0G2F.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_twist', 'Barbell Standing Twist', 'Břicho', '{"obliques","Spodní záda"}', 'Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down. Engage your core and keep your back straight throughout the exercise. Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0112-yQe5HpE.gif', TRUE, 'weight_reps'),
  ('ex_bottoms_up', 'Bottoms-up', 'Břicho', '{"obliques","Ohybače kyčlí"}', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and bring them towards your chest, keeping your feet off the ground. Engaging your abs, lift your hips off the ground, bringing your knees towards your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0138-CI6baTY.gif', TRUE, 'reps_only'),
  ('ex_bridge_mountain_climber_cross_body', 'Bridge - Mountain Climber (cross Body)', 'Břicho', '{"Hýždě","Kvadricepsy","Hamstringy"}', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow. Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2466-9c6T1YX.gif', TRUE, 'reps_only'),
  ('ex_butt_ups', 'Butt-ups', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides, palms facing down. Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0870-qcNN2FN.gif', TRUE, 'reps_only'),
  ('ex_cable_judo_flip', 'Cable Judo Flip', 'Břicho', '{"obliques","Ramena"}', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands at chest level, palms facing down. Engage your core and rotate your torso to the right, pulling the cable across your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0174-MvQPqVW.gif', TRUE, 'weight_reps'),
  ('ex_cable_reverse_crunch', 'Cable Reverse Crunch', 'Břicho', '{"Ohybače kyčlí"}', 'Attach a cable to a low pulley and lie down facing up on a mat. Hold the cable with both hands and extend your arms straight up towards the ceiling. Bend your knees and lift your legs up, bringing your thighs towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0873-RqOtqD7.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_crunch', 'Cable Seated Crunch', 'Břicho', '{"obliques"}', 'Sit on a cable machine with your feet flat on the ground and your knees bent. Hold the cable handle with both hands and position it behind your head. Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0212-8xUv4J7.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_twist', 'Cable Seated Twist', 'Břicho', '{"obliques"}', 'Sit on a cable machine with your feet flat on the ground and your knees slightly bent. Hold the cable handle with both hands and extend your arms straight in front of you. Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2399-UEjSrKI.gif', TRUE, 'weight_reps'),
  ('ex_cable_side_bend', 'Cable Side Bend', 'Břicho', '{"obliques"}', 'Stand with your feet shoulder-width apart and grasp the cable handle with one hand. Keep your back straight and your core engaged. Slowly bend sideways at the waist, lowering the cable handle towards your knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0222-wPypxFY.gif', TRUE, 'weight_reps'),
  ('ex_cable_side_crunch', 'Cable Side Crunch', 'Břicho', '{"obliques"}', 'Attach a cable handle to a low pulley and stand sideways to the machine. Grasp the handle with the hand furthest from the machine and place your other hand on your hip. Keep your feet shoulder-width apart and your knees slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0223-q2ADGqV.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_crunch', 'Cable Standing Crunch', 'Břicho', '{"obliques"}', 'Attach a cable handle to a high pulley and stand facing away from the machine. Hold the handle with both hands and place it behind your head, keeping your elbows bent. Stand with your feet shoulder-width apart and your knees slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0226-jpgqxiS.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_crunch_with_rope_attachment', 'Cable Standing Crunch (with Rope Attachment)', 'Břicho', '{"obliques"}', 'Attach a rope to a cable machine at chest height. Stand facing away from the machine with your feet shoulder-width apart. Hold the rope with both hands and bring it behind your head, keeping your elbows bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0874-XU3ePuv.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_lift', 'Cable Standing Lift', 'Břicho', '{"obliques","Spodní záda"}', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands and position it at waist height. Engage your core and maintain a straight back throughout the exercise.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0230-qFpAkpP.gif', TRUE, 'weight_reps'),
  ('ex_cable_tuck_reverse_crunch', 'Cable Tuck Reverse Crunch', 'Břicho', '{"Ohybače kyčlí"}', 'Attach a cable to a low pulley and lie down on a mat facing up. Hold the cable with both hands and extend your arms straight up above your chest. Bend your knees and lift your legs up, bringing your knees towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0242-TXtXc84.gif', TRUE, 'weight_reps'),
  ('ex_cable_twist_up_down', 'Cable Twist (up-down)', 'Břicho', '{"obliques","Spodní záda"}', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent. Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0862-fhZQPlV.gif', TRUE, 'weight_reps'),
  ('ex_captains_chair_straight_leg_raise', 'Captains Chair Straight Leg Raise', 'Břicho', '{"Ohybače kyčlí"}', 'Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads. Keep your upper body stable and your back straight. Engage your abs and lift your legs up in front of you, keeping them straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2963-weoDEpH.gif', TRUE, 'reps_only'),
  ('ex_cocoons', 'Cocoons', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0260-SLKj2pX.gif', TRUE, 'reps_only'),
  ('ex_crab_twist_toe_touch', 'Crab Twist Toe Touch', 'Břicho', '{"obliques","Ohybače kyčlí"}', 'Start by sitting on the ground with your knees bent and feet flat on the floor. Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground. Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1468-xgsGFVM.gif', TRUE, 'reps_only'),
  ('ex_cross_body_crunch', 'Cross Body Crunch', 'Břicho', '{"obliques"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0262-rbu5UUb.gif', TRUE, 'reps_only'),
  ('ex_crunch_hands_overhead', 'Crunch (hands Overhead)', 'Břicho', '{"Ohybače kyčlí"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight above your head. Engaging your abs, lift your upper body off the ground, curling forward towards your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0267-kjJ3VoQ.gif', TRUE, 'reps_only'),
  ('ex_curl_up', 'Curl-up', 'Břicho', '{"Ohybače kyčlí"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3016-g2oKspu.gif', TRUE, 'reps_only'),
  ('ex_dead_bug', 'Dead Bug', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your arms extended towards the ceiling. Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees. Engage your core and lower back to press your lower back into the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0276-iny3m5y.gif', TRUE, 'reps_only'),
  ('ex_decline_crunch', 'Decline Crunch', 'Břicho', '{"Ohybače kyčlí"}', 'Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle. Place your hands behind your head or across your chest. Engage your abs and lift your upper body towards your knees, curling your torso.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0277-9Ap7miY.gif', TRUE, 'reps_only'),
  ('ex_astride_jumps_male', 'Astride Jumps (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively upwards, extending your legs and arms.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3220-f9lVSSI.gif', TRUE, 'duration'),
  ('ex_back_and_forth_step', 'Back and Forth Step', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Step forward with your right foot, bending your knee and lowering your body into a lunge position. Push off with your right foot and step back to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3672-fNGumX0.gif', TRUE, 'duration'),
  ('ex_bear_crawl', 'Bear Crawl', 'Kardio', '{"Střed těla","Ramena","Triceps"}', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Lift your knees slightly off the ground, keeping your back flat and your core engaged. Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3360-0Yz8WdV.gif', TRUE, 'duration'),
  ('ex_burpee', 'Burpee', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you. Kick your feet back into a push-up position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1160-dK9394r.gif', TRUE, 'duration'),
  ('ex_cycle_cross_trainer', 'Cycle Cross Trainer', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Adjust the seat height and position yourself on the cycle cross trainer. Place your feet on the pedals and grip the handlebars. Start pedaling in a smooth and controlled motion.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2331-XSCHmiI.gif', TRUE, 'duration'),
  ('ex_dumbbell_burpee', 'Dumbbell Burpee', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand. Lower your body into a squat position, placing the dumbbells on the ground in front of you. Kick your feet back into a push-up position, keeping your body in a straight line.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1201-0JtKWum.gif', TRUE, 'duration'),
  ('ex_half_knee_bends_male', 'Half Knee Bends (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body down as if you were sitting back into a chair. Keep your chest up and your weight in your heels.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3221-ia6kIIl.gif', TRUE, 'duration'),
  ('ex_high_knee_against_wall', 'High Knee Against Wall', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand facing a wall with your feet hip-width apart. Place your hands on the wall for support. Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3636-ealLwvX.gif', TRUE, 'duration'),
  ('ex_jack_burpee', 'Jack Burpee', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position, placing your hands on the ground in front of you. Kick your feet back, landing in a push-up position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0501-mr7pkqP.gif', TRUE, 'duration'),
  ('ex_jack_jump_male', 'Jack Jump (male)', 'Kardio', '{"Kvadricepsy","Lýtka"}', 'Stand with your feet together and your arms by your sides. Jump up, spreading your feet apart and raising your arms above your head. As you land, quickly jump back to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3224-1g5bPpA.gif', TRUE, 'duration'),
  ('ex_push_to_run', 'Push to Run', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping your body straight. Push through your hands to extend your arms and return to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3638-PrQbjvB.gif', TRUE, 'duration'),
  ('ex_run', 'Run', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0685-oLrKqDH.gif', TRUE, 'duration'),
  ('ex_run_equipment', 'Run (equipment)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0684-y5p0H8a.gif', TRUE, 'duration'),
  ('ex_scissor_jumps_male', 'Scissor Jumps (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart. Jump off the ground and simultaneously cross your right leg in front of your left leg. As you land, quickly switch legs, crossing your left leg in front of your right leg.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3219-Eh2v5Iu.gif', TRUE, 'duration'),
  ('ex_semi_squat_jump_male', 'Semi Squat Jump (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively, extending your hips and knees while swinging your arms for momentum.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3222-6FMU51h.gif', TRUE, 'duration'),
  ('ex_short_stride_run', 'Short Stride Run', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Find an open space or a treadmill to perform the exercise. Stand tall with your feet hip-width apart. Start jogging in place, lifting your knees high and pumping your arms.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3656-CcWEoWV.gif', TRUE, 'duration'),
  ('ex_skater_hops', 'Skater Hops', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump to the right, landing on your right foot. As you land, swing your left leg behind your right leg and tap the ground with your left toes.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3361-zfNHMN9.gif', TRUE, 'duration'),
  ('ex_ski_step', 'Ski Step', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Bend your knees slightly and keep your back straight. Jump to the right, landing on your right foot while swinging your left leg behind your right leg.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3671-5MRH8H2.gif', TRUE, 'duration'),
  ('ex_star_jump_male', 'Star Jump (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend your knees slightly and jump up explosively. As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3223-HtfCpfi.gif', TRUE, 'duration'),
  ('ex_swing_360', 'Swing 360', 'Kardio', '{"Ramena","Střed těla"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold your arms straight out in front of you, parallel to the ground. Engage your core and swing your arms in a circular motion, rotating your torso as you do so.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3318-tnaj0mT.gif', TRUE, 'duration')
